b6X(a){return"up to "+a+"\xb0"},
b5t(a,b){return"AIR "+a+" s \xb7 "+b+" G"},
gbiz(){return"Wheelie detected"},
biy(a,b,c){return a+" s \xb7 "+b+" m \xb7 "+c+"\xb0 \u2014 right?"},
gS6(){return"Correct"},
gS5(){return"Wasn't one"},
gbix(){return"Wheelie, jump and stoppie measurement running"},
gbiw(){return"No banner after a wheelie, jump or stoppie? Tap \u201cMissed \u2026\u201d right afterwards."},
alI(a){return"Missed one noted at "+a+"."},
ga3B(){return"Missed wheelie"},
gb_H(){return"Jump detected"},
