gTo(){return"Missed stoppie"},
gaHo(){return"What the model sees"},
gaHj(){return"riding"},
gaHl(){return"Front up"},
gaHk(){return"Front down"},
gaHi(){return"Airborne"},
aHm(a,b){return a+" s \xb7 max "+b+"\xb0"},
aHn(a){return a+" s"},
gaHp(){return"Waiting for the sensors \u2026"},
gaHf(){return"Learning the mount: ride calmly for a moment"},
gaHe(){return"Learning \u201cforward\u201d: corners and braking help"},
aHd(a,b){return a+" km/h \xb7 "+b+" s behind"},
